root=pathlib.Path.cwd();out=root/'obj/parallel/all-attribute-selected-output-v1';out.mkdir(parents=True)
app=root/'obj/rust/dev-fast/rustgm';sha=lambda p:hashlib.sha256(p.read_bytes()).hexdigest()
subprocess.run(['timeout','30s',sys.executable,'scripts/storage.py','run','--no-prune','--',sys.executable,'scripts/setup_backend.py'],check=True)
tools=load_tools(('lowir','lowir2native'));records=[]
for case in selected:
 path=root/case['path'];assert sha(path)==case['sha256']
 folder=out/case['name'];folder.mkdir()
 commands=[]
 def run(argv,label):
  result=subprocess.run(argv,capture_output=True,timeout=15);commands.append({'argv':list(map(str,argv)),'status':result.returncode})
  (folder/(label+'.stdout')).write_bytes(result.stdout);(folder/(label+'.stderr')).write_bytes(result.stderr)
  return result
 args={'path':path.relative_to(root/'pa31').as_posix(),'exit_status':0,'rustc':{'kind':'program','status':0},'native':{'outcome':'pass'}}
 _,actual=course.run_case(root,'pa31','--emit-lowir',args,[str(app)],15)
 for suffix,data in zip(('stdout','stderr','status'),actual):(folder/('frontend.'+suffix)).write_bytes(data)
 check_native.accepted_frontend(actual)
 lowir=folder/'input.lowir';lowir.write_bytes(actual[0]);validated=folder/'validated.lowir';executable=folder/'native-output'
 for argv,label in [([tools['lowir'],'-o',str(validated),str(lowir)],'validate'),([tools['lowir2native'],'-O0','-o',str(executable),str(validated)],'backend')]:
  result=run(argv,label);assert result.returncode==0,(case['name'],label,result.stderr)
 result=run([str(executable)],'native-run');check_native.execution(result,'pass','cppgm')
 record={**case,'commands':commands,'candidate_sha256':sha(app),'native_sha256':sha(executable),'passed':True};records.append(record);executable.unlink();(out/'binding.json').write_text(json.dumps({'cases':records,'candidate_sha256':sha(app),'independent_results_sha256':'1ed21780a4cb959bfa9f0ff5461a68be4e70d32daa967b9ebb62b577201f19b5','compiler_source_sha256':{str(p):sha(p) for p in sorted(pathlib.Path('dev').rglob('*.rs'))}},indent=2)+'\n')
